grammar:
grammar Stmts {
  @root
  Root ::= { Statement } ;
  Statement ::= 'let' Name '=' Value ';' | 'print' Value ';' ;
  Name ::= 'n' ;
  Value ::= 'v' | '(' Value ')' ;
}

grammar Stmts {
  @root
  Root ::= { Statement } ;
  @autoCommit
  Statement ::= 'let' Name '=' Value ';' | 'print' Value ';' ;
  Name ::= 'n' ;
  Value ::= 'v' | '(' Value ')' ;
}

grammar Overlap {
  @root
  Root ::= 'a' B | 'a' C ;
  B ::= 'b' ;
  C ::= 'c' ;
}

grammar Resume {
  @root
  Root ::= Item 'x' | 'a' 'y' ;
  Item ::= 'a' B ;
  B ::= 'b' ;
}

grammar Follow {
  @root
  Root ::= [ Item ] Tail | Other ;
  Item ::= 'a' B ;
  Tail ::= 'a' 'z' ;
  Other ::= 'o' Item ;
  B ::= 'b' ;
}

grammar FollowOk {
  @root
  Root ::= [ Item ] Tail ;
  Item ::= 'a' B ;
  Tail ::= 'z' 'z' ;
  B ::= 'b' ;
}

grammar Blocks {
  @root
  Root ::= Block ;
  Block ::= '{' { Stmt } '}' ;
  Stmt ::= 'x' Semi | Block ;
  Semi ::= ';' ;
}

grammar Plus {
  @root
  Root ::= ( 'a' B )+ 'a' 'c' ;
  B ::= 'b' ;
}

grammar Lists {
  @root
  Root ::= Call ;
  Call ::= 'f' '(' Arg % ',' ')' ;
  Arg ::= 'k' Name | 'v' ;
  Name ::= 'n' ;
}

grammar TrailingComma {
  @root
  Root ::= 'f' '(' Arg % ',' [ ',' ] ')' ;
  Arg ::= 'k' Name | 'v' ;
  Name ::= 'n' ;
}

grammar Spaced {
  @whitespace: javaStyle
  @root
  Root ::= { Statement } ;
  Statement ::= 'let' Name ';' | 'print' Name ';' ;
  Name ::= 'n' ;
}

grammar RuleSpaced {
  @root
  Root ::= { Statement } ;
  @whitespace(javaStyle)
  Statement ::= 'let' Name ';' | 'print' Name ';' ;
  Name ::= 'n' ;
}

grammar Raised {
  @root
  Root ::= 'k' Name | LABEL(lbl, 'c' Name) | CATCH('d' Name, 'e', lbl) | COMMIT('f' Name) ;
  Name ::= 'n' ;
}

grammar Captured {
  @root
  Root ::= 'k' Name | CAPTURE(word, 'w' Name) SAME_AS(word) ;
  Name ::= 'n' ;
}

grammar Longest {
  @root
  Root ::= Pick ;
  @longestChoice
  Pick ::= Item | 'z' Name ;
  Item ::= 'a' Name ;
  Unused ::= 'u' Name ;
  Name ::= 'n' ;
}

grammar Recover {
  @root
  Root ::= { Statement } ;
  @recovery(sync=';')
  Statement ::= 'let' Name ';' | 'print' Name ';' ;
  Name ::= 'n' ;
}

grammar Tokens {
  @ubnf: v2
  token DIGIT ::= CHAR_RANGE('0','9');
  token NUM ::= DIGIT+ ;
  token KW ::= 'let' | 'var' ;
  @root
  Root ::= { Stmt } ;
  Stmt ::= KW Name | NUM Name | 'q' Name ;
  Name ::= 'n' ;
}

grammar Unknown {
  token Ahead = LOOKAHEAD('x')
  token Insensitive = CI('k')
  @root
  Root ::= { Stmt } ;
  Stmt ::= 'k' Name | Ahead Name | Insensitive Name | 'z' Name ;
  Name ::= 'n' ;
}

grammar Ranges {
  token Lower = CHAR_RANGE('a','z')
  token Digit = CHAR_RANGE('0','9')
  @root
  Root ::= { Stmt } ;
  Stmt ::= Lower Digit | 'Z' Lower ;
}

grammar Params {
  @root
  Root ::= { Stmt } ;
  Stmt ::= Kw('let') Name Tok('=') Name | 'print' Name ;
  Kw(w) ::= w ;
  Tok(t) ::= t ;
  Name ::= 'n' ;
}

grammar LeftRec {
  @root
  Root ::= Root '+' Name | 'k' Name ;
  Name ::= 'n' ;
}

grammar Roots {
  @root
  A ::= 'a' Name ;
  @root
  B ::= 'b' Name ;
  Name ::= 'n' ;
}

grammar Wide {
  @root
  Root ::= { Stmt } ;
  Stmt ::= 'α' Name | 'β' Name | 'k' Name ;
  Name ::= 'n' ;
}
